/** Verified host transport adapter; separate from isolated LuckyRay.call grants. */
interface MaterialLibraryConsumerTarget { readonly libraryId: string; readonly requestId: string; }
interface MaterialLibraryCapture extends MaterialLibraryConsumerTarget { name: string; mimeType: "image/png" | "text/markdown" | "text/plain"; bytesBase64: string; targetFolderId?: string; newFolderName?: string; tagIds?: string[]; tagNames?: string[]; description?: string; sourcePageUrl?: string; sourcePageKind?: "capture-page" | "work-page"; sourcePageTitle?: string; }
interface MaterialLibraryCaptureOperation extends MaterialLibraryConsumerTarget { readonly body: Readonly<MaterialLibraryCapture>; }
interface MaterialLibraryReceipt extends MaterialLibraryConsumerTarget { consumerVersion: 1; disposition: "imported" | "duplicate"; changed: boolean; assetId: string; assetName: string; asset: { id: string; name: string; kind: string; mimeType: string; sizeBytes: number; storageMode: "managed" | "source" | "linked"; description: string; folderId: string | null; tagIds: string[]; revision: string }; atomic: false; view: { available: false; reason: string }; warning?: { code: string; message: string }; }
interface MaterialLibraryConsumerClient { select(libraryId: string): { libraryId: string; epoch: number }; libraries(): Promise<unknown>; taxonomy(requestId: string): Promise<unknown>; query(requestId: string, filter?: object): Promise<unknown>; detail(requestId: string, assetId: string): Promise<unknown>; prepareCapture(input: Omit<MaterialLibraryCapture,"libraryId"> & { libraryId?: string }): MaterialLibraryCaptureOperation; save(operation: MaterialLibraryCaptureOperation): Promise<{ receipt: MaterialLibraryReceipt; current: boolean }>; snapshot(): { libraryId: string | null; epoch: number }; }
declare const LuckyRayMaterialLibraries: { version: 1; create(request: (method: "GET" | "POST", path: string, body?: object) => Promise<unknown>): MaterialLibraryConsumerClient; };
